/// <summary>
/// MPJ_17989 - kscerri - 12/14/2021
/// Class <c>METCustTransListingUIBuilder</c> UI builder
/// </summary>
class METCustAuditReportUIBuilder extends SrsReportDataContractUIBuilder
{
    METCustAuditReportContract    contract;
    DialogField                   fromDateChange, toDateChange, custAccount, custGroup, legalEntity;
    container                     conContainer;


}

Method.Source:
    /// <summary>
    /// MPJ_17989 - kscerri - 12/14/2021
    /// Builds dialog fields
    /// </summary>
    public void build()
    {
        contract = this.dataContractObject() as METCustAuditReportContract;

        fromDateChange  = this.addDialogField(methodStr(METCustAuditReportContract, parmFromDateChange), contract);
        custAccount     = this.addDialogField(methodStr(METCustAuditReportContract, parmCustAccount), contract);
        legalEntity     = this.addDialogField(methodStr(METCustAuditReportContract, parmLegalEntity), contract);
        toDateChange    = this.addDialogField(methodStr(METCustAuditReportContract, parmToDateChange), contract);
        custGroup       = this.addDialogField(methodStr(METCustAuditReportContract, parmCustGroup), contract);
    }

    /// <summary>
    /// MPJ_17989 - kscerri - 12/14/2021
    /// Maps dialog fields above to contract method
    /// </summary>
    public void postBuild()
    {
        super();

        contract = this.dataContractObject() as METCustAuditReportContract;

        fromDateChange = this.bindInfo().getDialogField(contract, methodStr(METCustAuditReportContract, parmFromDateChange));
        custAccount    = this.bindInfo().getDialogField(contract, methodStr(METCustAuditReportContract, parmCustAccount));
        toDateChange   = this.bindInfo().getDialogField(contract, methodStr(METCustAuditReportContract, parmToDateChange));
        custGroup      = this.bindInfo().getDialogField(contract, methodStr(METCustAuditReportContract, parmCustGroup));
        legalEntity    = this.bindInfo().getDialogField(contract, methodStr(METCustAuditReportContract, parmLegalEntity));

        legalEntity.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METCustAuditReportUIBuilder, legalEntityLookup), this);
        custAccount.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METCustAuditReportUIBuilder, custAcclookup), this);
        custGroup.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METCustAuditReportUIBuilder, custGrouplookup), this);
    }

    /// <summary>
    /// MPJ_17989 - kscerri - 12/14/2021
    /// legal entity lookup
    /// </summary>
    /// <param name = "parmFormStringControl">dialog field</param>
    public void legalEntityLookup(FormStringControl parmFormStringControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    tableQBDS;

        tableQBDS = query.addDataSource(tableNum(companyinfo));

        tableQBDS.addSelectionField(fieldNum(companyinfo, DataArea));
        tableQBDS.addSelectionField(fieldNum(companyinfo, Name));
        tableQBDS.addOrderByField(fieldnum(companyinfo, DataArea));

        SysLookupMultiSelectGrid::lookup(query,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         conContainer);
    }

    /// <summary>
    /// MPJ_17989 - kscerri - 12/14/2021
    /// Vendor table lookup
    /// </summary>
    /// <param name = "parmFormStringControl">dialog field</param>
    public void custAcclookup(FormStringControl parmFormStringControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    tableQBDS;

        tableQBDS =   query.addDataSource(tableNum(custTable));
        query.allowCrossCompany(true);
        tableQBDS.addSelectionField(fieldNum(custTable, AccountNum));
        tableQBDS.addSelectionField(fieldNum(custTable, Party));
        tableQBDS.addSelectionField(fieldNum(custTable, DataAreaId));

        SysLookupMultiSelectGrid::lookup(query,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         conContainer);
    }

    /// <summary>
    /// MPJ_17989 - kscerri - 12/14/2021
    /// Vendor group lookup
    /// </summary>
    /// <param name = "parmFormStringControl">dialog field</param>
    public void custGrouplookup(FormStringControl parmFormStringControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    tableQBDS;

        tableQBDS =   query.addDataSource(tableNum(custGroup));
        query.allowCrossCompany(true);

        tableQBDS.addSelectionField(fieldNum(custGroup, CustGroup));
        tableQBDS.addSelectionField(fieldNum(custGroup, Name));
        tableQBDS.addOrderByField(fieldnum(custGroup, CustGroup));
        tableQBDS.orderMode(OrderMode::GroupBy);
        tableQBDS.addOrderByField(fieldnum(custGroup, Name));
        tableQBDS.orderMode(OrderMode::GroupBy);

        SysLookupMultiSelectGrid::lookup(query,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         conContainer);
    }

